import { lstat, readdir, rmdir, unlink } from 'node:fs/promises';
import { basename, dirname, relative, resolve, sep } from 'node:path';

/**
 * Remove only the JSON metadata files generated by bundle-license-plugin.mjs.
 *
 * The target is derived internally from the package directory so callers
 * cannot pass an arbitrary recursive-delete path. Unexpected contents are
 * preserved and fail the build for inspection.
 */
export async function removeGeneratedLicenseMetadata(packageDir) {
  const packageRoot = resolve(packageDir);
  const distDir = resolve(packageRoot, 'dist');
  const metadataDir = resolve(distDir, '.license-meta');
  const expectedRelativePath = ['dist', '.license-meta'].join(sep);

  if (
    relative(packageRoot, metadataDir) !== expectedRelativePath ||
    dirname(metadataDir) !== distDir ||
    basename(metadataDir) !== '.license-meta'
  ) {
    throw new Error(`Refusing to clean unexpected license metadata path: ${metadataDir}`);
  }

  let metadataInfo;
  try {
    metadataInfo = await lstat(metadataDir);
  } catch (error) {
    if (error?.code === 'ENOENT') return;
    throw error;
  }

  if (!metadataInfo.isDirectory() || metadataInfo.isSymbolicLink()) {
    throw new Error(`Refusing to clean non-directory license metadata path: ${metadataDir}`);
  }

  const entries = await readdir(metadataDir, { withFileTypes: true });
  for (const entry of entries) {
    if (
      !entry.isFile() ||
      entry.isSymbolicLink() ||
      !/^[A-Za-z0-9][A-Za-z0-9._-]*\.json$/.test(entry.name)
    ) {
      throw new Error(
        `Refusing to clean unexpected license metadata entry: ${resolve(metadataDir, entry.name)}`,
      );
    }
  }

  for (const entry of entries) {
    await unlink(resolve(metadataDir, entry.name));
  }
  await rmdir(metadataDir);
}
